/** Browser-only handoff that preserves the click gesture for popup blockers.
 * It deliberately accepts only the referral generated by the trusted server. */
export type MessengerPopup = Pick<Window, "location" | "focus" | "close"> | null;

export function beginMessengerHandoff(openWindow: (url?: string, target?: string) => Window | null): MessengerPopup {
  return openWindow("about:blank", "importadora-messenger-order");
}

export function completeMessengerHandoff(popup: MessengerPopup, href: string) {
  if (!popup) return false;
  popup.location.assign(href);
  popup.focus();
  return true;
}

export function cancelMessengerHandoff(popup: MessengerPopup) {
  popup?.close();
}
